package com.loopers.application.event;import com.loopers.domain.event.OutboxEvent;import com.loopers.domain.order.Order;import com.loopers.infrastructure.event.OutboxJpaRepository;import com.loopers.infrastructure.order.OrderJpaRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
// Hides: the atomic order/outbox local transaction.
@Component @RequiredArgsConstructor public class OrderOutboxService{private final OrderJpaRepository orders;private final OutboxJpaRepository outbox;@Transactional public OutboxEvent create(String eventId,long buyer,long amount,boolean fail){Order o=orders.save(new Order(buyer,amount));OutboxEvent e=outbox.save(new OutboxEvent(eventId,String.valueOf(o.getId()),"order-confirmed:"+o.getId()));if(fail)throw new IllegalStateException("forced rollback");return e;}}
